import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); 

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type McDonaldsAnimationProps = Record<string, any>;

const McDonaldsAnimation: React.FC<McDonaldsAnimationProps> = ({
  backgroundColor = "#DA291C",
  transparentBackground = false,
  durationInSeconds = 5,
  archColor = "#FFC72C",
  logoScale = 1.2,
  strokeWidth = 18,
  sloganText = "Malloy Studio",
  sloganColor = "#FFFFFF",
}) => {

  {/* Load Google Fonts */}
  useFontLoader(["Montserrat"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const s = Math.min(width, height);

  // --- Animation Calculations ---

  // 1. Draw the arches (SVG Path Stroke Offset)
  const drawProgress = interpolate(frame, [15, 60], [100, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // 2. Spring pop when drawing completes
  const popSpring = spring({
    frame: Math.max(0, frame - 55),
    fps,
    config: {
      damping: 10,
      mass: 0.8,
      stiffness: 150,
    },
  });
  
  // Base scale based on responsive minimum dimension + user scale
  const baseSize = s * 0.4 * logoScale;
  const activeScale = 1 + (popSpring * 0.05);

  // 3. Slogan fade in and slide up
  const textOpacity = interpolate(frame, [65, 85], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const textY = interpolate(frame, [65, 85], [40, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Precise SVG Path for the Golden Arches
  // Left Arch: starts bottom left, peaks top left, drops to center.
  // Right Arch: continues from center, peaks top right, drops to bottom right.
  const archPath = "M 25 150 C 35 10, 90 10, 100 110 C 110 10, 165 10, 175 150";

  return (
    <AbsoluteFill 
      style={{ 
        backgroundColor: bgColor, 
        fontFamily: "Montserrat",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        transition: "none"
      }}
    >
      
      {/* Container for Logo and Text */}
      <div 
        style={{ 
          display: "flex", 
          flexDirection: "column", 
          alignItems: "center",
          transform: `scale(${activeScale})`,
          transition: "none",
        }}
      >
        {/* Golden Arches SVG */}
        <div
          style={{
            width: baseSize,
            height: baseSize * 0.8, // Aspect ratio of 200x160 viewBox
            transition: "none"
          }}
        >
          <svg
            viewBox="0 0 200 160"
            style={{
              width: "100%",
              height: "100%",
              overflow: "visible",
              transition: "none",
              filter: `drop-shadow(0px 8px 16px rgba(0,0,0,0.15))`
            }}
          >
            <path
              d={archPath}
              fill="none"
              stroke={archColor}
              strokeWidth={strokeWidth}
              strokeLinecap="round"
              strokeLinejoin="round"
              pathLength="100"
              strokeDasharray="100"
              strokeDashoffset={drawProgress}
              style={{ transition: "none" }}
            />
          </svg>
        </div>

        {/* Slogan Text */}
        {sloganText && (
          <h2
            style={{
              marginTop: s * 0.05,
              fontSize: s * 0.045,
              fontWeight: 700,
              color: sloganColor,
              opacity: textOpacity,
              transform: `translateY(${textY}px)`,
              letterSpacing: "0.05em",
              transition: "none",
              textShadow: "0px 4px 12px rgba(0,0,0,0.2)"
            }}
          >
            {sloganText}
          </h2>
        )}
      </div>

    </AbsoluteFill>
  );
};

export default McDonaldsAnimation;